export function Scenario(seed: number = 2) {
  class Counter {
    static label = 'counter'
    value = seed
    increment() {
      this.value += 1
      return this.value
    }
  }
  const counter = new Counter()
  return [Counter.label, counter.value, counter.increment(), counter.value]
}

